27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "postcode")
47	    private String postcode;
48	
49	    @Column(name = "telephone")
50	    @NotEmpty
51	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ then 8 to 15 digits)")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    private String email;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "membership_number")
67	    private String membershipNumber;
68	
69	    @Column(name = "household_id")
70	    private String householdId;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Transient
76	    private Boolean bulkSignupWarning;
77	
78	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
79	    private Set<Pet> pets;
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
88	
89	    public String getCity() {
90	        return this.city;
91	    }
92	
93	    public void setCity(String city) {
94	        this.city = city;
95	    }
96	
97	    public String getPostcode() {
98	        return this.postcode;
99	    }
100	
101	    public void setPostcode(String postcode) {
102	        this.postcode = postcode;
103	    }
104	
105	    public String getTelephone() {
106	        return this.telephone;
107	    }
108	
109	    public void setTelephone(String telephone) {
110	        this.telephone = telephone;
111	    }
112	
113	    public String getEmail() {
114	        return this.email;
115	    }
116	
117	    public void setEmail(String email) {
118	        this.email = email;
119	    }
120	
121	    public LocalDate getRegistrationDate() {
122	        return this.registrationDate;
123	    }
124	
125	    public void setRegistrationDate(LocalDate registrationDate) {
126	        this.registrationDate = registrationDate;
127	    }
128	
129	    public LocalDate getBirthDate() {
130	        return this.birthDate;
131	    }
132	
133	    public void setBirthDate(LocalDate birthDate) {
134	        this.birthDate = birthDate;
135	    }
136	
137	    /**
138	     * The owner's age band, derived from {@link #getBirthDate() birthDate} measured against the
139	     * {@link #getRegistrationDate() registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
140	     * when 18 to 64, or {@code "SENIOR"} when 65 or older. {@code null} when no birth date is present
141	     * (so the field is absent from the response) or the registration date is unknown.
142	     */
143	    public String getAgeBand() {
144	        if (this.birthDate == null || this.registrationDate == null) {
145	            return null;
146	        }
147	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
148	        if (age < 18) {
149	            return "MINOR";
150	        }
151	        if (age < 65) {
152	            return "ADULT";
153	        }
154	        return "SENIOR";
155	    }
156	
157	    public String getCustomerCode() {
158	        return this.customerCode;
159	    }
160	
161	    public void setCustomerCode(String customerCode) {
162	        this.customerCode = customerCode;
163	    }
164	
165	    public String getMembershipNumber() {
166	        return this.membershipNumber;
167	    }
168	
169	    public void setMembershipNumber(String membershipNumber) {
170	        this.membershipNumber = membershipNumber;
171	    }
172	
173	    public String getHouseholdId() {
174	        return this.householdId;
175	    }
176	
177	    public void setHouseholdId(String householdId) {
178	        this.householdId = householdId;
179	    }
