181	    public Integer getNamesakeCount() {
182	        return this.namesakeCount;
183	    }
184	
185	    public void setNamesakeCount(Integer namesakeCount) {
186	        this.namesakeCount = namesakeCount;
187	    }
188	
189	    /**
190	     * Whether this response should carry a bulk-signup warning: {@code true} when more than 80 owners
191	     * have already been created for this owner's registration day. Computed per request, not persisted.
192	     */
193	    public Boolean getBulkSignupWarning() {
194	        return this.bulkSignupWarning;
195	    }
196	
197	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
198	        this.bulkSignupWarning = bulkSignupWarning;
199	    }
200	
201	    /**
202	     * The owner's membership level, a number from 1 to 3 fixed at creation. Starts at 1; add 1 when an
203	     * email is present; add 1 when {@code namesakeCount} is 0; capped at 3. Level 4 is reserved for
204	     * tenure and is never produced here.
205	     */
206	    public int getMembershipLevel() {
207	        int level = 1;
208	        boolean hasEmail = this.email != null && !this.email.isBlank();
209	        if (hasEmail) {
210	            level++;
211	        }
212	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
213	        if (unique) {
214	            level++;
215	        }
216	        return Math.min(level, 3);
217	    }
218	
219	    /**
220	     * Fixed city-to-region table mapping each known city to its canonical region string.
221	     */
222	    private static final Map<String, String> CITY_REGION = Map.of(
223	        "Sydney", "NSW",
224	        "Melbourne", "VIC",
225	        "Brisbane", "QLD");
226	
227	    /**
228	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
229	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
230	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
231	     */
232	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
233	        "NSW", new int[] {2000, 2099},
234	        "VIC", new int[] {3000, 3099},
235	        "QLD", new int[] {4000, 4099});
236	
237	    /**
238	     * The canonical region for {@code city} derived from the fixed city-to-region table
239	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
240	     * city is not in the table. The single source of truth for the create-time postcode range check in
241	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
242	     */
243	    public static String regionOf(String city) {
244	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
245	    }
246	
247	    /**
248	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
249	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
250	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
251	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
252	     * postcode range check.
253	     */
254	    public static int[] postcodeRangeOf(String region) {
255	        return REGION_POSTCODES.get(region);
256	    }
257	
258	    /**
259	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
260	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
261	     * range.
262	     */
263	    public static String regionOfPostcode(String postcode) {
264	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
265	            return null;
266	        }
267	        int value = Integer.parseInt(postcode);
268	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
269	            int[] range = entry.getValue();
270	            if (value >= range[0] && value <= range[1]) {
271	                return entry.getKey();
272	            }
273	        }
274	        return null;
275	    }
276	
277	    /**
278	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
279	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
280	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
281	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
282	     * customer code is assigned.
283	     */
284	    public String getLocality() {
285	        if (this.customerCode == null) {
286	            return "UNKNOWN";
287	        }
288	        int dash = this.customerCode.indexOf('-');
289	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
290	    }
291	
292	    /**
293	     * The single Luhn check digit (0-9) computed over the digits contained in the
294	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
295	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
296	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
297	     */
298	    public int getCheckDigit() {
299	        String code = this.customerCode;
300	        if (code == null) {
301	            return 0;
302	        }
303	        int sum = 0;
304	        boolean dbl = true;
305	        for (int i = code.length() - 1; i >= 0; i--) {
306	            char c = code.charAt(i);
307	            if (c < '0' || c > '9') {
308	                continue;
309	            }
310	            int d = c - '0';
311	            if (dbl) {
312	                d *= 2;
313	                if (d > 9) {
314	                    d -= 9;
315	                }
316	            }
317	            sum += d;
318	            dbl = !dbl;
319	        }
320	        return (10 - (sum % 10)) % 10;
321	    }
322	
323	    /**
324	     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
325	     * {@code "PHONE"}.
326	     */
327	    public String getContactPreference() {
328	        boolean hasEmail = this.email != null && !this.email.isBlank();
329	        return hasEmail ? "EMAIL" : "PHONE";
330	    }
331	
332	    /**
333	     * The single canonical format of an owner's identity key — the one value all duplicate detection is
334	     * expressed through: {@code telephone + "|" + (email or empty) + "|" + (householdId or empty)}. The
335	     * telephone and household id are used as given (they are expected to already be canonical: E.164 and
336	     * an assigned household id); the email is lower-cased here and a null/blank email, telephone or
337	     * household id contributes an empty component. This is the only place the {@code "|"}-join lives;
338	     * every producer of the key (the stored-owner {@link #getIdentityKey()} and the create-time check in
339	     * {@code OwnerIdentity}) routes through here so the formats cannot drift.
340	     */
341	    public static String identityKey(String telephone, String email, String householdId) {
342	        String tel = (telephone == null) ? "" : telephone;
343	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
344	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
345	        return tel + "|" + mail + "|" + household;
346	    }
347	
348	    /**
349	     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and
350	     * household id via {@link #identityKey(String, String, String)}. Two owners are duplicates exactly
351	     * when their whole identity keys are equal.
352	     */
353	    public String getIdentityKey() {
354	        return identityKey(this.telephone, this.email, this.householdId);
355	    }
356	
357	    protected Set<Pet> getPetsInternal() {
358	        if (this.pets == null) {
359	            this.pets = new HashSet<>();
360	        }
361	        return this.pets;
362	    }
363	
364	    protected void setPetsInternal(Set<Pet> pets) {
365	        this.pets = pets;
366	    }
367	
368	    public List<Pet> getPets() {
369	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
370	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
371	        return Collections.unmodifiableList(sortedPets);
372	    }
373	
374	    public void setPets(List<Pet> pets) {
375	        this.pets = new HashSet<>(pets);
376	    }
377	
378	    public void addPet(Pet pet) {
379	        getPetsInternal().add(pet);
380	        pet.setOwner(this);
381	    }
382	
383	    /**
384	     * Return the Pet with the given name, or null if none found for this Owner.
385	     *
386	     * @param name to test
387	     * @return true if pet name is already in use
388	     */
389	    public Pet getPet(String name) {
390	        return getPet(name, false);
391	    }
392	
393	    /**
394	     * Return the Pet with the given name, or null if none found for this Owner.
395	     *
396	     * @param name to test
397	     * @return true if pet name is already in use
398	     */
399	    public Pet getPet(String name, boolean ignoreNew) {
400	        name = name.toLowerCase();
401	        for (Pet pet : getPetsInternal()) {
402	            if (!ignoreNew || !pet.isNew()) {
403	                String compName = pet.getName();
404	                compName = compName.toLowerCase();
405	                if (compName.equals(name)) {
406	                    return pet;
407	                }
408	            }
409	        }
410	        return null;
411	    }
412	
413	    public Pet getPet(Integer petId) {
414	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
415	    }
416	
417	    @Override
418	    public String toString() {
419	        return new ToStringCreator(this)
420	
421	            .append("id", this.getId())
422	            .append("new", this.isNew())
423	            .append("lastName", this.getLastName())
424	            .append("firstName", this.getFirstName())
425	            .append("address", this.address)
426	            .append("city", this.city)
427	            .append("telephone", this.telephone)
428	            .toString();
429	    }
430	}
