1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
10	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
11	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	/**
15	 * Validates a new owner before {@link BuildOwner} runs: every one of firstName, lastName, address,
16	 * city and telephone must be present and non-blank. Any that are missing or blank are collected and
17	 * reported together as a {@link MissingOwnerFieldsException} (a 400), so the body is never persisted.
18	 *
19	 * <p>The telephone is then normalized to E.164 (keep a leading '+' and country code when present,
20	 * otherwise assume '+61' and drop a single leading '0' from the national digits, stripping spaces,
21	 * dashes and brackets and requiring 8 to 15 digits after the '+'); otherwise an
22	 * {@link InvalidTelephoneException} (a 400) is raised. The E.164 value is written back onto the request
23	 * so downstream steps store and return it.
24	 *
25	 * <p>Deliberately does <em>not</em> use {@code @Valid}: bean validation would raise a
26	 * {@code MethodArgumentNotValidException} with a different response shape, whereas this rule must
27	 * answer with an {@code errors} array naming each offending field.
28	 */
29	public class ValidateNewOwner {
30	
31	    /**
32	     * Syntactic email check (the HTML5/Hibernate-Validator {@code @Email} form): a local part of the
33	     * permitted characters, an {@code @}, then a dot-separated domain of label segments. Used only to
34	     * decide between accept and 400; a valid value is then lower-cased and written back onto the request.
35	     */
36	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
37	            "^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?"
38	                    + "(?:\\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$");
39	
40	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
41	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
42	        // This list mirrors OwnerFieldsDto's required fields by hand: it must track the schema's
43	        // `required` set. We check presence/non-blankness only, a narrower rule than the DTO's full
44	        // constraints (@Size/@Pattern), so bean validation is intentionally not used here.
45	        // Normalize the address first so the required-field check rejects an address that is blank
46	        // after normalization (e.g. "   "), and so downstream steps store/return and compare the
47	        // canonical form. OwnerAddress.normalize yields "" for a null or all-whitespace address.
48	        String normalizedAddress = OwnerAddress.normalize(request.getAddress());
49	        request.setAddress(normalizedAddress);
50	
51	        List<String> missing = new ArrayList<>();
52	        require(missing, "firstName", request.getFirstName());
53	        require(missing, "lastName", request.getLastName());
54	        require(missing, "address", normalizedAddress);
55	        require(missing, "city", request.getCity());
56	        require(missing, "telephone", request.getTelephone());
57	        if (!missing.isEmpty()) {
58	            throw new MissingOwnerFieldsException(missing);
59	        }
60	
61	        // Normalize the telephone to E.164. Store the canonical value back so BuildOwner/SaveOwner
62	        // persist it and the response echoes the E.164 form.
63	        String e164 = OwnerTelephone.toE164(request.getTelephone());
64	        if (e164 == null) {
65	            throw new InvalidTelephoneException(request.getTelephone());
66	        }
67	        request.setTelephone(e164);
68	
69	        // Email is optional: only an email that is present (non-blank) must be a valid address. A valid
70	        // value is lower-cased and written back (like telephone above) so downstream steps store and
71	        // return the canonical form.
72	        String email = request.getEmail();
73	        if (email != null && !email.isBlank()) {
74	            if (!EMAIL_PATTERN.matcher(email).matches()) {
75	                throw new InvalidEmailException(email);
76	            }
77	            request.setEmail(email.toLowerCase());
78	        }
79	
80	        validated.set(request);
81	    }
82	
83	    private static void require(List<String> missing, String field, String value) {
84	        if (value == null || value.isBlank()) {
85	            missing.add(field);
86	        }
87	    }
88	}
