1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
6	
7	/**
8	 * Rejects a new owner whose supplied {@code registrationDate} is later than the server's current date:
9	 * an owner cannot be registered in the future, so the request is answered with a 400 Bad Request. A
10	 * request that omits the date is accepted (it defaults to the server date in {@link BuildOwner}). Runs
11	 * among the create-time validations, before {@link BuildOwner} stores the (possibly adjusted) date.
12	 */
13	public class ValidateRegistrationDate {
14	
15	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
16	        if (RegistrationDates.isFuture(request.getRegistrationDate())) {
17	            throw new FutureRegistrationDateException(request.getRegistrationDate());
18	        }
19	    }
20	}
