1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
9	
10	/**
11	 * Validates an owner's postcode when one is supplied, so an unacceptable value is a 400 before the
12	 * owner is ever persisted. Runs after the body has been bound and published (by {@link ValidateNewOwner}
13	 * on create / {@link ValidateOwner} on update) and before the owner is built or loaded.
14	 *
15	 * <p>Postcode is optional: a {@code null} or blank value is left untouched and accepted. When present it
16	 * must be exactly four digits; otherwise it is rejected. The city's region is derived through the single
17	 * {@link Owner#regionOf(String) city-to-region table}, and when the region is known the postcode must
18	 * fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
19	 * no known region accepts any four-digit postcode.
20	 */
21	public class ValidateOwnerPostcode {
22	
23	    /** A postcode is exactly four digits. */
24	    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");
25	
26	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
27	        String postcode = request.getPostcode();
28	        if (postcode == null || postcode.isBlank()) {
29	            return; // optional when absent — request contract stays backward-compatible
30	        }
31	        if (!POSTCODE.matcher(postcode).matches()) {
32	            throw new InvalidPostcodeException(postcode, "must be four digits");
33	        }
34	        int[] range = Owner.postcodeRangeOf(Owner.regionOf(request.getCity()));
35	        if (range != null) {
36	            int value = Integer.parseInt(postcode);
37	            if (value < range[0] || value > range[1]) {
38	                throw new InvalidPostcodeException(postcode,
39	                        "out of range " + range[0] + "-" + range[1] + " for city '" + request.getCity() + "'");
40	            }
41	        }
42	    }
43	}
