1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The single duplicate check for a new owner. All duplicate detection is consolidated into one derived
11	 * {@code identityKey} (see {@link OwnerIdentity}): a new owner is rejected with a 409 Conflict only when
12	 * its WHOLE identity key equals an existing owner's. This replaces the separate telephone, email and
13	 * household checks.
14	 *
15	 * <p>The {@code householdId} component of the key is derived and assigned only once an owner is created
16	 * ({@link AssignHousehold} runs after this check), so at this point it is not yet known: both the
17	 * candidate and the owners it is compared against contribute an empty household component. Because the
18	 * normalized telephone is part of the key, two members of the same household with different telephones
