3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Single source of truth for household identity. A household groups owners that share the same last
10	 * name and the same address, compared case-insensitively with surrounding and internal whitespace
11	 * collapsed (so "Smith" / " smith " and "10  Main St" / "10 Main St" belong together).
12	 *
13	 * <p>The {@link #id(String, String)} derived from that normalized pair is stable: the same last name
14	 * and address always map to the same value, so every member of a household — including one that joins
15	 * via {@code sharesHousehold} — receives an identical {@code householdId}.
16	 */
17	final class Household {
18	
19	    private Household() {
20	    }
21	
22	    /** Lower-case (locale-independent) with leading/trailing and repeated internal whitespace collapsed. */
23	    private static String normalize(String value) {
24	        if (value == null) {
25	            return "";
26	        }
27	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
28	    }
29	
30	    /**
31	     * The canonical household key for a (lastName, address) pair — the single definition of household
32	     * membership. Two owners belong to the same household exactly when their keys are equal; {@link #id}
33	     * hashes this same key, so the duplicate check and the assigned id can never diverge.
34	     *
35	     * <p>Addresses are compared in their {@link OwnerAddress normalized} form (whitespace collapsed,
36	     * upper-cased, abbreviations expanded) so that equivalent spellings — "12 main st" and
37	     * "12 MAIN STREET" — belong to the same household even when stored data was not normalized.
38	     */
39	    static String key(String lastName, String address) {
40	        return normalize(lastName) + "\n" + OwnerAddress.normalize(address);
41	    }
42	
43	    /**
44	     * Stable household identifier for the given last name and address: {@code "H-"} followed by the
45	     * first 12 hex characters of the SHA-256 of the {@link #key household key}.
46	     */
47	    static String id(String lastName, String address) {
48	        String key = key(lastName, address);
49	        try {
50	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
51	            StringBuilder sb = new StringBuilder("H-");
52	            for (int i = 0; i < 6; i++) {
53	                sb.append(String.format("%02x", digest[i]));
54	            }
55	            return sb.toString();
56	        }
57	        catch (NoSuchAlgorithmException e) {
58	            throw new IllegalStateException("SHA-256 not available", e);
59	        }
60	    }
61	}
