20	 * blank (and therefore missing) address.
21	 */
22	final class OwnerAddress {
23	
24	    /** Whole-word abbreviations expanded during normalization (keys are already upper-cased). */
25	    private static final Map<String, String> ABBREVIATIONS = Map.of(
26	            "ST", "STREET",
27	            "RD", "ROAD",
28	            "AVE", "AVENUE");
29	
30	    private OwnerAddress() {
31	    }
32	
33	    /**
34	     * Returns the normalized form of {@code address}, or the empty string when it is {@code null} or
35	     * blank after trimming.
36	     */
37	    static String normalize(String address) {
38	        if (address == null) {
39	            return "";
40	        }
41	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
42	        if (collapsed.isEmpty()) {
43	            return "";
44	        }
45	        String[] tokens = collapsed.split(" ");
46	        StringBuilder sb = new StringBuilder(collapsed.length());
47	        for (int i = 0; i < tokens.length; i++) {
48	            if (i > 0) {
49	                sb.append(' ');
50	            }
51	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
52	        }
53	        return sb.toString();
54	    }
55	}
