29	    private static final Pattern E164 = Pattern.compile("^\\+[0-9]{8,15}$");
30	
31	    /** Characters removed before interpreting the number: spaces, dashes and brackets. */
32	    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");
33	
34	    /**
35	     * Country code (without the '+') to its required national-number length. Iterated longest-code-first
36	     * (hence {@link LinkedHashMap}) so a longer code is matched before a shorter one that is a prefix of
37	     * the number. Country codes absent here are not length-checked.
38	     */
39	    private static final Map<String, Integer> NATIONAL_LENGTHS;
40	    static {
41	        Map<String, Integer> lengths = new LinkedHashMap<>();
42	        lengths.put("61", 9); // Australia
43	        lengths.put("1", 10); // North American Numbering Plan
44	        NATIONAL_LENGTHS = lengths;
45	    }
46	
47	    private OwnerTelephone() {
48	    }
49	
50	    /**
51	     * Returns the E.164 form of {@code telephone}, or {@code null} when it cannot form valid E.164.
52	     */
53	    static String toE164(String telephone) {
54	        if (telephone == null) {
55	            return null;
56	        }
57	        String cleaned = SEPARATORS.matcher(telephone).replaceAll("");
58	        String digits;
59	        if (cleaned.startsWith("+")) {
60	            // Keep the explicit country code; the '+' is re-added below.
61	            digits = cleaned.substring(1);
62	        }
63	        else {
64	            // No country code: assume +61 and drop a single leading '0' from the national digits.
65	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
66	            digits = "61" + national;
67	        }
68	        String e164 = "+" + digits;
69	        if (!E164.matcher(e164).matches()) {
70	            return null;
71	        }
72	        return hasValidNationalLength(digits) ? e164 : null;
73	    }
74	
75	    /**
76	     * Whether the national-number length of {@code digits} (a '+'-less E.164 digit string) matches its
77	     * country code. Unrecognized country codes pass (checked only by the general 8-to-15 rule above).
78	     */
79	    private static boolean hasValidNationalLength(String digits) {
80	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTHS.entrySet()) {
81	            String code = entry.getKey();
82	            if (digits.startsWith(code)) {
83	                return digits.length() - code.length() == entry.getValue();
84	            }
85	        }
86	        return true;
87	    }
88	}
